DROP TABLE IF EXISTS `t_alarm_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_alarm_rule` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `class_id` int NOT NULL COMMENT '病害类别ID',
  `class_name` varchar(80) NOT NULL COMMENT '病害类别名称',
  `conf_threshold` decimal(6,4) NOT NULL DEFAULT '0.5000' COMMENT '触发告警的置信度阈值',
  `alarm_level` varchar(10) NOT NULL DEFAULT '中' COMMENT '告警等级：高/中/低',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用：1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_id` (`class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='告警规则表';
/*!40101 SET character_set_client = @saved_cs_client */;

