CREATE TABLE `t_detect_detail` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_id` int NOT NULL COMMENT '所属检测记录ID',
  `class_id` int DEFAULT NULL COMMENT '类别ID',
  `class_name` varchar(80) DEFAULT NULL COMMENT '类别名称',
  `confidence` decimal(6,4) DEFAULT '0.0000' COMMENT '置信度',
  `x1` decimal(10,2) DEFAULT '0.00' COMMENT '框左上角X',
  `y1` decimal(10,2) DEFAULT '0.00' COMMENT '框左上角Y',
  `x2` decimal(10,2) DEFAULT '0.00' COMMENT '框右下角X',
  `y2` decimal(10,2) DEFAULT '0.00' COMMENT '框右下角Y',
  PRIMARY KEY (`id`),
  KEY `idx_record_id` (`record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13565 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检测明细表';
