DROP TABLE IF EXISTS `t_detect_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_detect_record` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int DEFAULT NULL COMMENT '检测用户ID',
  `model_id` int DEFAULT NULL COMMENT '使用的模型ID',
  `detect_type` varchar(20) NOT NULL COMMENT '检测类型：image/video/realtime',
  `source_name` varchar(200) DEFAULT NULL COMMENT '原始文件名',
  `source_path` varchar(255) DEFAULT NULL COMMENT '原始文件相对路径',
  `result_path` varchar(255) DEFAULT NULL COMMENT '结果文件相对路径',
  `target_count` int DEFAULT '0' COMMENT '检测到的目标数量',
  `top_class` varchar(80) DEFAULT NULL COMMENT '最高置信度类别名称',
  `top_confidence` decimal(6,4) DEFAULT '0.0000' COMMENT '最高置信度',
  `conf_threshold` decimal(6,4) DEFAULT '0.2500' COMMENT '本次使用的置信度阈值',
  `cost_ms` int DEFAULT '0' COMMENT '推理耗时（毫秒）',
  `detect_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '检测时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_detect_time` (`detect_time`)
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检测记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

