INSERT INTO `t_kg_relation` VALUES (1,'黄瓜','患','霜霉病','doc1793401476_c505','2026-10-31 07:04:57'),(2,'霜霉病','表现为','水渍状浅绿色斑点','doc1793401476_c505','2026-10-31 07:04:57'),(3,'霜霉病','表现为','多角形','doc1793401476_c505','2026-10-31 07:04:57'),(4,'霜霉病','表现为','灰黑色霉层','doc1793401476_c505','2026-10-31 07:04:57'),(5,'霜霉病','表现为','病斑变褐干枯','doc1793401476_c505','2026-10-31 07:04:57'),(6,'霜霉病','表现为','叶片自下而上枯死','doc1793401476_c505','2026-10-31 07:04:57'),(7,'霜霉病','发生于','低温高湿','doc1793401476_c505','2026-10-31 07:04:57'),(8,'霜霉病','阈值为','16–24℃','doc1793401476_c505','2026-10-31 07:04:57'),(9,'霜霉病','阈值为','85% 以上','doc1793401476_c505','2026-10-31 07:04:57'),(10,'霜霉病','用药','烯酰吗啉','doc1793401476_c505','2026-10-31 07:04:57'),(11,'霜霉病','用药','氟啶胺','doc1793401476_c505','2026-10-31 07:04:57'),(12,'霜霉病','用药','霜脲氰','doc1793401476_c505','2026-10-31 07:04:57'),(13,'霜霉病','用药','甲霜灵锰锌','doc1793401476_c505','2026-10-31 07:04:57'),(14,'霜霉病','措施','抗病品种','doc1793401476_c505','2026-10-31 07:04:57'),(15,'霜霉病','措施','控制棚内湿度','doc1793401476_c505','2026-10-31 07:04:57'),(16,'霜霉病','措施','上午通风排湿','doc1793401476_c505','2026-10-31 07:04:57'),(17,'霜霉病','措施','避免大水漫灌','doc1793401476_c505','2026-10-31 07:04:57'),(18,'苹果黑星病','病原为','苹果黑星病菌','kb',NULL),(19,'苹果锈病','病原为','苹果胶锈菌','kb',NULL),(20,'甜椒叶斑病','病原为','甜椒叶斑病菌','kb',NULL),(21,'玉米灰斑病','病原为','玉米灰斑病菌','kb',NULL),(22,'玉米大斑病','病原为','玉米大斑病菌','kb',NULL),(23,'玉米锈病','病原为','玉米柄锈菌','kb',NULL),(24,'马铃薯早疫病','病原为','链格孢菌','kb',NULL),(25,'马铃薯晚疫病','病原为','致病疫霉','kb',NULL),(26,'大豆叶部异常','病原为','大豆花叶病毒','kb',NULL),(27,'南瓜白粉病','病原为','葫芦科白粉病菌','kb',NULL),(28,'番茄早疫病','病原为','番茄早疫病菌','kb',NULL),(29,'番茄褐斑病','病原为','番茄褐斑病菌','kb',NULL),(30,'番茄细菌性斑点病','病原为','丁香假单胞菌番茄致病变种','kb',NULL),(31,'番茄晚疫病','病原为','致病疫霉','kb',NULL),(32,'番茄花叶病毒病','病原为','番茄花叶病毒','kb',NULL),(33,'番茄黄化曲叶病毒病','病原为','番茄黄化曲叶病毒','kb',NULL),(34,'番茄叶霉病','病原为','番茄叶霉病菌','kb',NULL),(35,'葡萄黑腐病','病原为','葡萄黑腐病菌','kb',NULL);
