--
-- Table structure for table `t_knowledge`
--

DROP TABLE IF EXISTS `t_knowledge`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_knowledge` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL COMMENT '标准中文名',
  `name_en` varchar(160) DEFAULT NULL COMMENT '英文/拉丁名',
  `crop` varchar(120) DEFAULT NULL,
  `category` varchar(20) DEFAULT NULL COMMENT '病害/虫害/健康',
  `symptom` text,
  `harm` text,
  `control_plan` text,
  `level` varchar(10) DEFAULT NULL,
  `source` varchar(160) DEFAULT NULL COMMENT '来源：t_disease / kb / web',
  `filled_by` varchar(20) DEFAULT NULL COMMENT 'manual / llm / web',
  `verified` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=810 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识条目表';
/*!40101 SET character_set_client = @saved_cs_client */;

