/*!40000 ALTER TABLE `t_knowledge` DISABLE KEYS */;
INSERT INTO `t_knowledge` VALUES (1,'苹果黑星病',NULL,'苹果','病害','叶片正面出现近圆形黑褐色病斑，边缘呈放射状，潮湿时病斑上产生绒状黑霉层，严重时叶片扭曲、早落。','导致叶片提早脱落，树势衰弱，果实产量和品质下降，连续多年发生会明显削弱树体。','清除病叶落叶并深埋；萌芽前喷施石硫合剂；发病初期选用戊唑醇、苯醚甲环唑等药剂交替喷雾，注意雨后补喷。','高','t_disease','manual',1,'2026-11-02 06:13:13'),(2,'苹果健康叶片',NULL,'苹果','健康','叶片翠绿、完整，叶脉清晰，无明显病斑、黄化或畸形。','健康叶片是光合作用的基础，有利于树体积累养分、提高坐果率和果实品质。','保持均衡施肥与合理修剪，注意通风透光；定期巡田，发现异常及时处理。','低','t_disease','manual',1,'2026-11-02 06:13:13'),(3,'苹果锈病',NULL,'苹果','病害','叶片正面出现橙黄色近圆形病斑，背面着生锈黄色毛状物（锈孢子器），严重时叶片布满锈斑并早落。','影响光合作用，引起早期落叶，降低果实糖度和产量，靠近柏树的果园更易流行。','果园远离或清除转主寄主柏树；萌芽期喷保护性杀菌剂；发病初期用三唑酮、氟硅唑等防治。','中','t_disease','manual',1,'2026-11-02 06:13:13'),(4,'甜椒健康叶片',NULL,'甜椒','健康','叶片深绿色、厚实有光泽，边缘完整，无斑点和萎蔫。','健康叶片保证光合效率，有利于果实膨大与着色。','合理密植、控水控肥，保持田间通风；预防蚜虫等传毒媒介。','低','t_disease','manual',1,'2026-11-02 06:13:13'),(5,'甜椒叶斑病',NULL,'甜椒','病害','叶片上出现圆形或不规则褐色病斑，中央灰白、边缘深褐，潮湿时病斑扩大并连片，严重时叶片枯死脱落。','造成大量落叶，植株光合能力下降，果实日灼和减产明显。','选用抗病品种；避免连作；发病初期喷施代森锰锌、苯醚甲环唑等药剂，及时摘除病叶。','中','t_disease','manual',1,'2026-11-02 06:13:13'),(6,'蓝莓健康叶片',NULL,'蓝莓','健康','叶片椭圆形、深绿色有光泽，叶缘光滑或浅锯齿，无明显病斑。','健康叶片保障浆果糖分积累和植株越冬养分储备。','保持酸性土壤（pH 4.5-5.5），适量补充铁肥，注意排水防涝。','低','t_disease','manual',1,'2026-11-02 06:13:13'),(7,'樱桃健康叶片',NULL,'樱桃','健康','叶片卵圆形、先端尖，叶色鲜绿，叶缘有锯齿，无穿孔和黄化。','健康叶片直接关系到樱桃产量与果实风味。','加强夏季修剪改善通风；雨季注意褐斑病、穿孔病预防。','低','t_disease','manual',1,'2026-11-02 06:13:13'),(8,'玉米灰斑病',NULL,'玉米','病害','叶片上产生矩形或长条形灰色至褐色病斑，受叶脉限制呈平行条纹，后期病斑中央灰白、边缘褐色。','流行年份可造成大面积叶片枯死，减产 20%-50%，是玉米产区重要叶部病害。','选用抗病品种；合理轮作；抽雄前后喷施吡唑醚菌酯、苯醚甲环唑等药剂。','高','t_disease','manual',1,'2026-11-02 06:13:13'),(9,'玉米大斑病',NULL,'玉米','病害','叶片出现梭形大斑，初期水渍状，后变为黄褐色至灰褐色，病斑长达数厘米，严重时整叶枯死。','破坏叶面积，影响灌浆，可造成严重减产，高温高湿年份尤为突出。','种植抗病品种；清除田间病残体；发病初期喷施戊唑醇、嘧菌酯等，适当早播避病。','高','t_disease','manual',1,'2026-11-02 06:13:13'),(10,'玉米锈病',NULL,'玉米','病害','叶片两面散生黄褐色至红褐色疱状夏孢子堆，破裂后散出铁锈状粉末，后期出现黑色冬孢子堆。','削弱光合能力，籽粒不饱满，南方高温高湿地区流行风险高。','选用抗锈品种；合理密植与施肥；发病初期喷三唑酮、烯唑醇等。','中','t_disease','manual',1,'2026-11-02 06:13:13'),(11,'桃健康叶片',NULL,'桃','健康','叶片披针形或长椭圆，叶色鲜绿，叶缘有细锯齿，无缩叶和穿孔。','健康叶片是桃树成花与果实膨大的基础。','注意缩叶病、细菌性穿孔病预防，合理冬剪，避免偏施氮肥。','低','t_disease','manual',1,'2026-11-02 06:13:13'),(12,'马铃薯健康叶片',NULL,'马铃薯','健康','复叶小叶卵圆形，叶色浓绿，表面光滑，无病斑和卷叶。','健康叶片保证块茎膨大期的养分供应。','轮作换茬，使用脱毒种薯，注意晚疫病监测。','低','t_disease','manual',1,'2026-11-02 06:13:13'),(13,'马铃薯早疫病',NULL,'马铃薯','病害','叶片出现圆形或近圆形褐色病斑，具明显同心轮纹（靶斑），周围常有黄色晕圈，下部老叶先发病。','引起早期落叶，块茎变小，一般减产 10%-25%。','增施钾肥提高抗性；发病初期喷代森锰锌、苯醚甲环唑；避免田间积水。','中','t_disease','manual',1,'2026-11-02 06:13:13'),(14,'马铃薯晚疫病',NULL,'马铃薯','病害','叶尖或叶缘出现水渍状暗绿色病斑，迅速扩大呈褐色，潮湿时叶背着生白霉，干燥时病斑脆裂。','毁灭性病害，可在短期内使地上部枯死并侵染块茎，造成严重减产甚至绝收。','使用脱毒种薯；监测预警后及时喷施烯酰吗啉、氟啶胺等；发现中心病株立即拔除。','高','t_disease','manual',1,'2026-11-02 06:13:13'),(15,'树莓健康叶片',NULL,'树莓','健康','叶片掌状复叶，叶面深绿、背面灰绿有绒毛，边缘有锯齿。','健康叶片有利于浆果着色和香气物质积累。','保持行间通风，雨季注意灰霉和叶斑病预防。','低','t_disease','manual',1,'2026-11-02 06:13:14'),(16,'大豆健康叶片',NULL,'大豆','健康','三出复叶，小叶卵圆形，叶色鲜绿，无黄斑和花叶。','健康叶片保障鼓粒期干物质积累，影响百粒重。','合理密植，注意胞囊线虫与锈病监测，平衡施肥。','低','t_disease','manual',1,'2026-11-02 06:13:14'),(17,'大豆叶部异常',NULL,'大豆','病害','叶片出现黄化、斑驳或局部坏死等异常症状，需结合田间环境进一步诊断。','影响光合效率，严重时造成落叶和荚数减少。','加强田间诊断，区分缺素、病毒与真菌性病害后对症防治；注意蚜虫等传毒媒介防控。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(18,'南瓜白粉病',NULL,'南瓜','病害','叶面先出现白色近圆形粉斑，随后扩展连片覆盖一层白粉，后期叶片发黄枯死。','降低光合效率，果实膨大受阻、品质下降，保护地栽培尤为常见。','降低田间湿度、改善通风；发病初期喷施醚菌酯、腈菌唑或小苏打溶液，严重时摘除病叶。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(19,'草莓健康叶片',NULL,'草莓','健康','三出复叶，小叶近圆形，叶色浓绿有光泽，锯齿明显。','健康叶片是草莓高产优质的基础，直接影响花芽分化。','避免积水，合理覆盖地膜，注意白粉病和炭疽病预防。','低','t_disease','manual',1,'2026-11-02 06:13:14'),(20,'番茄早疫病',NULL,'番茄','病害','叶片出现圆形褐色病斑，具同心轮纹，周围有黄晕，通常从下部老叶向上扩展。','造成落叶，果实日灼，产量下降，高温高湿下扩展迅速。','轮作、清除病残体；发病初期喷代森锰锌、苯醚甲环唑；适当整枝改善通风。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(21,'番茄褐斑病',NULL,'番茄','病害','叶片产生圆形小斑点，中央灰白、边缘深褐，其上可见小黑点（分生孢子器），严重时病斑愈合导致叶片枯死。','引起大量落叶，植株早衰，果实产量和商品性下降。','避免连作；滴灌降低叶面湿度；喷施百菌清、嘧菌酯等保护与治疗药剂。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(22,'番茄健康叶片',NULL,'番茄','健康','奇数羽状复叶，小叶深绿色有缺刻，叶面略有绒毛，无斑点和卷曲。','健康叶片保障番茄连续坐果与转色。','均衡水肥，及时整枝打杈，保持田间通风透光。','低','t_disease','manual',1,'2026-11-02 06:13:14'),(23,'番茄细菌性斑点病',NULL,'番茄','病害','叶片出现水渍状小斑点，后变为暗褐色并带黄色晕圈，潮湿时病斑可愈合，严重时叶片黄化脱落。','降低光合面积，果实表面也可出现斑点，影响商品价值。','使用无病种子；避免叶面长时间潮湿；发病初期喷春雷霉素、铜制剂，注意与真菌病害区分。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(24,'番茄晚疫病',NULL,'番茄','病害','叶缘或叶尖出现水渍状灰绿色大斑，迅速变为褐色，潮湿时叶背长出稀疏白霉，可蔓延至茎和果实。','流行速度快，可在数天内毁园，是番茄最危险的病害之一。','选用抗病品种；夜间降湿；发现中心病株立即喷烯酰吗啉、霜脲氰等，并摘除病叶。','高','t_disease','manual',1,'2026-11-02 06:13:14'),(25,'番茄花叶病毒病',NULL,'番茄','病害','叶片呈现黄绿相间的花叶、斑驳，叶片变小、皱缩或畸形，植株矮化。','严重影响植株生长和坐果，果实变小、品质变差，蚜虫传毒后难以根治。','防治蚜虫；及时拔除病株；选用抗病品种；农事操作避免汁液传播，工具消毒。','高','t_disease','manual',1,'2026-11-02 06:13:14'),(26,'番茄黄化曲叶病毒病',NULL,'番茄','病害','顶部嫩叶黄化、变小并向上卷曲，植株矮化，开花坐果明显减少。','由烟粉虱传播，一旦发生损失极大，可造成接近绝收。','严防烟粉虱；苗期覆盖防虫网；发现病株立即拔除并销毁；选用抗TY品种。','高','t_disease','manual',1,'2026-11-02 06:13:14'),(27,'番茄叶霉病',NULL,'番茄','病害','叶面出现不规则淡黄色病斑，叶背着生灰紫色至黑褐色绒状霉层，严重时叶片干枯。','保护地高湿环境下易流行，引起大量功能叶坏死，产量下降。','加强通风排湿；合理密植；喷施嘧菌酯、春雷·王铜等，摘除下部病叶。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(28,'番茄二斑叶螨',NULL,'番茄','虫害','叶面出现密集失绿小斑点，逐渐黄白，叶背可见细小螨虫和蛛丝，严重时叶片焦枯如火烧状。','刺吸汁液导致叶片功能丧失，影响果实膨大，高温干燥时爆发快。','保持田间湿度；释放捕食螨；点片发生时选用阿维菌素、联苯肼酯等轮换用药。','中','t_disease','manual',1,'2026-11-02 06:13:14'),(29,'葡萄健康叶片',NULL,'葡萄','健康','叶片近圆形，3-5 裂，叶色深绿，叶脉明显，无病斑和白粉。','健康叶片决定葡萄糖度、着色和树体贮藏养分。','合理负载，及时绑蔓摘心，注意霜霉病和白粉病预防。','低','t_disease','manual',1,'2026-11-02 06:13:14'),(30,'葡萄黑腐病',NULL,'葡萄','病害','叶片出现近圆形红褐色病斑，中央浅褐、边缘深褐，其上着生小黑点，也可危害果实形成黑色僵果。','引起早期落叶和果穗腐烂，潮湿年份损失严重。','清园销毁病残体；开花前后喷代森锰锌、戊唑醇；及时摘除病叶病果。','高','t_disease','manual',1,'2026-11-02 06:13:14'),(31,'稻纵卷叶螟','rice_leaf_roller','水稻','虫害','幼虫吐丝将水稻叶片纵卷成筒状虫苞，匿居其中取食叶肉，仅留透明表皮，形成白色条斑；初孵幼虫可为害心叶，出现针头状白点。','导致功能叶光合能力下降，空壳率增加、千粒重降低，严重时白叶满田、大幅减产。','抓住2–3龄幼虫关键期施药，推荐使用1.8%阿维菌素乳油15–20克/亩，或45%毒死蜱乳油60–80毫升/亩，兑水50公斤均匀喷雾，连防2–3次，间隔5–7天。','重','联网搜索','llm',0,'2026-11-02 06:23:41'),(32,'稻螟蛉','rice_leaf_caterpillar','水稻','虫害','幼虫1—2龄将稻叶食成白色条纹，3龄后从叶缘咬食形成缺刻，严重时叶片破碎仅留中肋；幼虫行动似尺蠖，受惊即跳跃落水并游至他株继续为害。','秧苗期受害最重，影响光合作用，导致生长迟缓、分蘖减少，严重时可致缺苗断垄。','农业防治：及时清除田边杂草、处理稻茬；物理防治：灯光诱杀成虫；生物防治：释放赤眼蜂寄生卵块；化学防治：在低龄幼虫期喷施90%敌百虫晶体800倍液或25%杀虫双水剂500倍液。','中','联网搜索','llm',0,'2026-11-02 06:23:48'),(33,'稻秆潜蝇','paddy_stem_maggot','水稻','虫害','幼虫蛀食水稻心叶、生长点和幼穗，导致叶片纵裂、破碎、枯心；抽穗困难，颖壳现孔口并腐烂，形成扭曲短小白穗或残缺穗；受害新叶5–7天后显现症状。','造成白穗、烂穗、减产，严重田块产量损失数成，山区高发区危害可超三化螟和稻纵卷叶螟。','铲除田边禾本科杂草以减少越冬虫源；培育壮苗带药移栽；药剂防治可选用10%吡虫啉可湿性粉剂、70%吡虫啉+氯虫苯甲酰胺、1.8%阿维菌素或1%甲维盐喷雾。','中','联网搜索','llm',0,'2026-11-02 06:23:55'),(34,'二化螟','asiatic_rice_borer','水稻','虫害','幼虫钻蛀水稻茎秆，分蘖期造成枯鞘、枯心苗，孕穗至抽穗期导致枯孕穗、白穗和虫伤株；初孵幼虫群集叶鞘为害，三龄后分散蛀茎。','一般年份减产3%-5%，严重时减产30%以上，局部可致绝收。','抓住卵孵化盛期至低龄幼虫高峰期施药；推荐使用四氯虫酰胺、乙多·甲氧虫、或短稳杆菌等交替轮换用药，避免长期单一使用氯虫苯甲酰胺等已产生高水平抗性的药剂。','重','联网搜索','llm',0,'2026-11-02 06:24:05'),(35,'三化螟','yellow_rice_borer','水稻','虫害','幼虫钻蛀稻茎，苗期造成枯心苗，孕穗期至抽穗期形成枯孕穗、白穗；蛀入孔小、无虫粪外露，茎内有白色细粒虫粪；心叶纵卷呈葱管状（假枯心），断面整齐。','严重时导致大面积白穗、颗粒无收，常年造成1%-5%产量损失。','农业防治：冬闲田灌水灭蛹、及时处理稻桩；生物防治：释放赤眼蜂；化学防治：在卵孵高峰期喷施氯虫苯甲酰胺、阿维·氯苯酰或杀虫双，注意轮换用药以延缓抗性。','重','联网搜索','llm',0,'2026-11-02 06:24:12'),(36,'稻瘿蚊','rice_gall_midge','水稻','虫害','幼虫蛀入水稻心叶基部取食生长点，致心叶不能正常展开，叶鞘愈合形成淡绿色中空葱管状结构（俗称“标葱”或“葱管”），植株基部膨大，心叶停止生长。','受害稻株不能抽穗结实，严重时整丛枯死，导致大幅减产甚至绝收。','在成虫盛发期至卵孵化高峰期，亩用5%毒死蜱颗粒剂1.5–1.8公斤拌适量干细土或肥料撒施；也可喷施吡虫啉或三唑磷乳油。注意保持田间水层5–7天，并避免高温中午施药。','重','联网搜索','llm',0,'2026-11-02 06:24:19'),(37,'稻秆潜蝇','Rice_Stemfly','水稻','虫害','幼虫蛀入心叶、生长点及幼穗，苗期心叶出现椭圆形小孔，后发展为纵裂条状，致叶片破碎、扭曲或枯萎；孕穗期受害形成白穗、扭曲短穗、花白穗或‘喜鹊尾’状畸形穗。','导致分蘖增多、植株矮化、抽穗延迟、穗小秕谷增加，严重时减产10–30%，局部失收。','防治适期为成虫盛发期和卵孵高峰期（如5月中旬、7月上中旬）；可选用20%阿维·三唑磷乳油50毫升/亩、或1.8%阿维菌素40–80毫升/亩、或80%敌敌畏乳油1000倍液喷雾，施药时保持3–5厘米浅水层。','中','联网搜索','llm',0,'2026-11-02 06:24:27'),(38,'褐飞虱','brown_plant_hopper','水稻','虫害','成虫和若虫群集于水稻基部茎秆和叶鞘背面，以刺吸式口器插入韧皮部吸食汁液；产卵时用产卵器刺破叶鞘组织，造成褐色条斑或枯黄斑块；严重时稻株基部变黑、腐烂，出现‘冒穿’或‘塌圈’现象。','导致水稻植株萎蔫、倒伏、枯死，严重减产甚至绝收，还可传播水稻齿叶矮缩病毒等病害。','加强田间监测，孕穗至抽穗期为重点防治期；药剂可选用25%吡蚜酮悬浮剂20–30克/亩、或10%烯啶虫胺水剂30–40毫升/亩，兑水喷雾，注意轮换用药以防抗性；结合合理肥水管理，避免偏施氮肥。','重','联网搜索','llm',0,'2026-11-02 06:24:34'),(39,'白背飞虱','white_backed_plant_hopper','水稻','虫害','成虫和若虫群集于稻丛基部茎鞘刺吸汁液，排出大量蜜露致叶鞘变黑、叶片发黄干枯；茎基部呈褐色条斑，严重时腐烂倒伏，形成‘黄塘’‘落窝’。','轻者减产20–30%，重者减产50%以上甚至绝收，并传播南方水稻黑条矮缩病毒。','在低龄若虫高峰期施药，每亩用70%吡虫啉水分散粒剂2–4克，或25%噻嗪酮可湿性粉剂50克，加水50千克均匀喷雾于茎叶基部。','重','联网搜索','llm',0,'2026-11-02 06:24:42'),(40,'灰飞虱','small_brown_plant_hopper','水稻','虫害','成虫和若虫刺吸水稻等禾本科作物汁液，致稻株黄化、矮缩、枯孕穗或白穗；喜栖植株上部叶鞘、剑叶及穗部；排泄蜜露诱发煤污病；产卵造成茎叶组织伤口。','直接导致减产，还可传播水稻条纹叶枯病毒和黑条矮缩病毒，引发大面积病毒病流行，造成严重产量损失。','农业防治包括选用抗（耐）虫品种、清除田边禾本科杂草、合理肥水管理；化学防治在低龄若虫高峰期喷施吡蚜酮、烯啶虫胺或呋虫胺，注意轮换用药以防抗性。','中','联网搜索','llm',0,'2026-11-02 06:24:49'),(41,'稻水象甲','rice_water_weevil','水稻','虫害','成虫沿叶脉啃食叶肉，形成白色长条斑；幼虫蛀食稻根，致根系断损、变黑腐烂，植株黄化、矮小、分蘖减少，严重时浮秧倒伏。','造成水稻减产15%–20%，重发田块减产超50%甚至绝收，威胁粮食安全。','坚持‘早发现、早防治’，推行带药移栽（如用30%氯虫·噻虫嗪悬浮剂浸秧根）、本田期喷施40%毒死蜱乳油或20%呋虫胺可溶粒剂；结合翻耕灭茬、清除田边杂草、灯光诱杀及严格检疫。','重','联网搜索','llm',0,'2026-11-02 06:24:57'),(42,'稻叶蝉','rice_leafhopper','水稻','虫害','成虫和若虫刺吸水稻等寄主汁液，致叶片出现棕褐色条斑、失绿、卷曲、枯黄甚至整株萎蔫；产卵于叶鞘内侧组织造成机械损伤。','导致植株生长受抑、分蘖减少、千粒重下降，并传播水稻矮缩病、黄矮病等病毒病，引发大面积减产甚至绝收。','清除田边杂草及冬闲田寄主，灯光诱杀成虫；重点在秧田期和分蘖初期喷药防治，可选用10%吡虫啉可湿性粉剂1500倍液或25%叶蝉散可湿性粉剂500倍液均匀喷雾。','重','联网搜索','llm',0,'2026-11-02 06:25:04'),(43,'稻苞虫','rice_shell_pest','水稻','虫害','幼虫吐丝将稻叶边缘卷曲成苞，藏匿其中取食叶肉，留下表皮呈白色条斑；低龄幼虫多在叶尖纵卷单叶苞，3龄后可缀合多叶成大苞，严重时整株叶片被吃光或仅剩中脉。','导致水稻光合作用下降、植株矮小、穗短粒少、灌浆不充分、千粒重降低，大发生年减产可达50%以上。','农业防治：冬春铲除田边杂草、茭白残株，减少越冬虫源；生物防治：保护利用黄带并区姬蜂、绒茧金小蜂等天敌；化学防治：幼虫3龄前喷施氯虫苯甲酰胺或90%晶体敌百虫75–100克/亩。','重','联网搜索','llm',0,'2026-11-02 06:25:14'),(44,'蛴螬','grub','玉米','虫害','幼虫在土壤中啃食作物地下根系、块茎、种子及幼苗根部，造成缺苗断垄；受害植株地上部表现为生长迟缓、叶片发黄、萎蔫甚至枯死；根部可见明显咬痕、断口或隧道状蛀道。','导致出苗率下降、植株早衰、产量显著降低，严重时整片田块毁种。','农业防治：深耕晒垡、轮作倒茬、清除田间杂草和秸秆；物理诱杀：灯光诱杀成虫；药剂防治：播种前用3%辛硫磷颗粒剂1.5–2 kg/亩拌土沟施，或苗期用50%辛硫磷乳油1000倍液灌根。','重','联网搜索','llm',0,'2026-11-02 06:25:22'),(45,'蝼蛄','mole_cricket','小麦','虫害','成虫和若虫在土中挖掘隧道，咬食种子、幼根、嫩茎及地下茎，造成缺苗断垄；地表可见蜿蜒隆起的虚土隧道，受害植株萎蔫枯死。','严重阻碍幼苗出土与生长，导致大面积缺苗、减产甚至毁种。','农业防治：深耕晒垡、施用腐熟有机肥；物理防治：黑光灯诱杀成虫；化学防治：用50%辛硫磷乳油拌种或制成毒饵（如辛硫磷+炒香麦麸）于傍晚撒施于虫道入口处。','重','联网搜索','llm',0,'2026-11-02 06:25:28'),(46,'金针虫','wireworm','小麦','虫害','幼虫在土壤中取食播种后的种子、幼芽、根系及地下茎，造成缺苗断垄；受害根茎常被咬成孔洞或残缺不全，伤口易诱发土传病害。','导致出苗率下降、植株生长衰弱、产量显著降低，严重时可造成大面积死苗。','播种前可用50%辛硫磷乳油1000倍液拌种或沟施；也可在幼虫发生期用90%敌百虫晶体1500–2000倍液灌根；结合深耕翻土、适时灌溉可有效压低虫口。','重','联网搜索','llm',0,'2026-11-02 06:25:35'),(47,'银纹夜蛾','white_margined_moth','大豆','虫害','幼虫初孵时群集叶背啃食叶肉，残留上表皮呈透明斑；3龄后分散为害，将叶片咬成孔洞、缺刻，严重时仅剩叶脉和叶柄；老熟幼虫在叶背吐丝结薄茧化蛹。','导致作物光合能力下降、生长受阻，严重时造成叶片大面积损毁、减产甚至绝收，并排泄粪便污染植株。','农业防治：清除田间枯枝落叶、翻耕灭蛹；物理防治：黑光灯诱杀成虫；生物防治：喷施Bt制剂或青虫菌粉剂（100亿孢子/g，1500倍液）；化学防治：低龄幼虫期喷施5%抑太保乳油2000倍液或50%马拉硫磷乳油1000倍液，间隔7–10天，连防1–2次。','中','联网搜索','llm',0,'2026-11-02 06:25:44'),(48,'小地老虎','black_cutworm','棉花','虫害','幼虫昼伏夜出，栖息于表土层，咬断幼苗近地面茎基部，造成缺苗断垄；高龄幼虫可钻入土中蛀食块根、块茎或啃食心叶，部分植株被拖入洞中取食。','严重时导致大面积死苗、毁种，影响作物出苗率和群体整齐度，降低产量与品质。','农业防治：深耕灭蛹、清除杂草、诱杀成虫（糖醋液或黑光灯）；化学防治：幼虫3龄前喷施2.5%高效氯氟氰菊酯乳油2000倍液，或5%氯虫苯甲酰胺悬浮剂1500倍液，重点喷洒苗基部及周围土壤。','重','联网搜索','llm',0,'2026-11-02 06:25:52'),(49,'大地老虎','large_cutworm','烟草','虫害','幼虫咬断幼苗近地面的茎基部或主根，造成植株倒伏、枯死；也可啃食嫩茎、生长点及叶片，低龄时在叶面蛀‘天窗’，高龄后转株为害，导致缺苗断垄。','严重时造成大面积缺苗、毁种，影响作物出苗率和田间整齐度，降低产量与品质。','早春清除田边杂草并沤肥处理；1–3龄幼虫期喷施90%晶体敌百虫800倍液或2.5%溴氰菊酯3000倍液；成虫期可用黑光灯或糖醋液（糖:醋:白酒:水=6:3:1:10，加90%敌百虫1份）诱杀。','中','联网搜索','llm',0,'2026-11-02 06:26:00'),(50,'黄地老虎','yellow_cutworm','玉米','虫害','幼虫昼伏夜出，咬断幼苗近地面茎部，造成缺苗断垄；高龄幼虫还可钻入土中取食块根、块茎或啃食植株地下部分，导致萎蔫或死亡。','严重时可造成大面积死苗，显著降低出苗率和产量。','农业防治结合药剂防治：清除田间杂草、深耕灭蛹；幼虫3龄前喷施2.5%高效氯氟氰菊酯乳油2000倍液，或5%甲维盐水分散粒剂3000倍液，傍晚施药效果更佳。','重','联网搜索','llm',0,'2026-11-02 06:26:06'),(51,'朱砂叶螨','red_spider','豇豆','虫害','成螨及若螨群集于叶片背面吸食汁液，初期叶面出现黄白色或苍白色失绿斑点，渐扩展为铁锈色或红褐色坏死斑；严重时叶背布满丝网，叶片变黄、焦枯、脱落。','导致光合作用下降、植株早衰、果实着色差、品质降低，严重时整株枯死，造成显著减产。','农业防治：轮作、清除田间杂草与枯枝落叶；生物防治：释放捕食螨、瓢虫等天敌；化学防治：喷施阿维菌素、联苯肼酯或哒螨灵，注意轮换用药以延缓抗性。','重','联网搜索','llm',0,'2026-11-02 06:26:14'),(52,'玉米螟','corn_borer','玉米','虫害','幼虫钻蛀心叶、茎秆、雄穗、雌穗及穗轴；心叶期被害后展开叶片呈整齐横排小孔（排孔）；雄穗被蛀致穗柄折断（折雄）；雌穗期蛀食花丝、苞叶、籽粒，蛀孔外堆有虫粪，易引发霉烂。','导致植株倒伏、雄穗败育、籽粒缺损与品质下降，常年造成5%–15%产量损失。','心叶末期喷施25%喹硫磷乳油150毫升/亩，或1%甲维盐乳油1500倍液；结合农业防治（秸秆粉碎还田或清烧）、释放赤眼蜂、性信息素诱杀及去雄等综合措施。','重','联网搜索','llm',0,'2026-11-02 06:26:21'),(53,'黏虫','army_worm','玉米','虫害','幼虫暴食禾本科作物叶片，初孵幼虫群集取食叶肉，留下表皮呈窗纱状；3龄后分散为害，可将整株叶片吃光，仅剩茎秆和叶脉；严重时幼虫成群迁移，如‘行军’状。','导致作物光合能力丧失、生长停滞，严重时绝收；大发生年份可造成数十万吨粮食损失。','抓住低龄幼虫期（3龄前）施药，推荐使用20%氯虫苯甲酰胺悬浮剂10–15 mL/亩，或5%甲维盐水分散粒剂20–30 g/亩，兑水喷雾；结合灯光诱杀成虫、清除田边杂草及保护利用步行甲、寄生蜂等天敌。','重','联网搜索','llm',0,'2026-11-02 06:26:29'),(54,'蚜虫','aphids','玉米','虫害','成虫与若虫群集于植物嫩叶背面、嫩茎、花器及幼果等部位刺吸汁液，致叶片卷缩、发黄、皱缩、生长迟缓；分泌大量蜜露覆盖叶面，诱发煤污病。','严重削弱植株长势，降低光合作用效率，传播玉米矮花叶病毒等多种植物病毒，造成显著减产和品质下降。','采取农业防治（清除田边杂草、合理控氮）、物理防治（悬挂黄板、铺设银灰膜驱避）和生物防治（保护瓢虫、草蛉、食蚜蝇等天敌）；化学防治可选用10%吡虫啉可湿性粉剂2000倍液喷雾，注意轮换用药以延缓抗性。','重','联网搜索','llm',0,'2026-11-02 06:26:37'),(55,'桃蛀螟','Potosiabre_vitarsis','桃','虫害','幼虫蛀入果实、嫩梢或果柄内取食，蛀孔外常有虫粪，果内充满虫粪并易腐烂；亦可蛀入新梢髓部致萎蔫枯死；部分寄主上还引起裂果、落果。','导致大量落果、虫果和品质下降，严重时‘十果九蛀’，显著降低产量与商品价值。','成虫期可布设性诱捕器或杀虫灯诱杀；幼果期及时套袋阻隔产卵；药剂防治宜在成虫盛发期及产卵高峰期喷施氯虫苯甲酰胺、吡虫啉或除虫脲等高效低毒药剂。','重','联网搜索','llm',0,'2026-11-02 06:26:44'),(56,'桃小食心虫','peach_borer','桃','虫害','幼虫蛀入果实，初在果皮下潜食形成针尖状蛀孔点，后沿果核外围螺旋取食，排粪于虫道内，致果肉褐变硬化、果实畸形（猴头果）、早期脱落；果面可见微凹陷红褐色点或隆起瘤状物。','果实商品价值丧失，严重时落果率超30%，产量损失达15%–30%。','越冬幼虫出土盛期（5月上旬，地温≥18℃）树冠下喷施25%辛硫磷微胶囊剂50倍液；成虫羽化高峰期（性诱剂日均诱蛾≥5头）喷施20%氯虫苯甲酰胺悬浮剂3000倍液，安全间隔期14天。','重','联网搜索','llm',0,'2026-11-02 06:26:52'),(57,'麦长管蚜','english_grain_aphid','小麦','虫害','成虫和若虫刺吸小麦茎、叶及嫩穗汁液；苗期致叶片发黄、生长停滞、分蘖减少；穗期致麦粒不饱满、穗干枯，严重时全株死亡。','造成产量下降、品质降低，并传播小麦黄矮病毒病等病毒病。','农业防治结合药剂防治：及时清除田边杂草，选用抗蚜品种；发生初期喷施10%吡虫啉可湿性粉剂2000倍液或25%噻虫嗪水分散粒剂3000倍液，注意轮换用药以防抗性。','重','联网搜索','llm',0,'2026-11-02 06:26:59'),(58,'麦二叉蚜','green_bug','小麦','虫害','成虫和若虫群集于麦株下部叶片背面刺吸汁液，致叶片发黄、卷曲、枯萎；可传播黄矮病毒等，叶背常有蜜露诱发煤污病。','造成小麦灌浆不足、千粒重下降、严重时整株萎蔫减产，还可传播病毒加剧危害。','农业防治：清除田边禾本科杂草寄主；生物防治：保护利用瓢虫、草蛉及寄生蜂Lysiphlebus testaceipes；药剂防治：在百株蚜量达500头时喷施10%吡虫啉可湿性粉剂2000倍液，或25%噻虫嗪水分散粒剂3000倍液。','重','联网搜索','llm',0,'2026-11-02 06:27:07'),(59,'禾谷缢管蚜','bird_cherry-oataphid','小麦','虫害','成虫和若蚜多聚集于小麦下部叶背面、叶鞘、根茎附近及抽穗后麦穗部，刺吸汁液；被害叶片纵向向叶背卷曲、黄化、枯落；分泌蜜露诱发煤污病。','导致小麦生长受阻、分蘖减少、千粒重下降、光合效率降低，并传播大麦黄矮病毒等，造成显著减产和品质劣化。','农业防治：适期播种、清除田边杂草寄主；生物防治：保护瓢虫、草蛉、蚜茧蜂等天敌；化学防治：在蚜量达防治指标时喷施10%吡虫啉可湿性粉剂（2000倍液）或25%抗蚜威可湿性粉剂（3000倍液），注意轮换用药以延缓抗性发展。','重','联网搜索','llm',0,'2026-11-02 06:27:15'),(60,'麦红吸浆虫','wheat_blossom_midge','小麦','虫害','幼虫潜伏于麦穗颖壳内，吸食灌浆期麦粒汁液，致籽粒干瘪、皱缩或成空壳；植株长势正常但贪青晚熟，穗直立不倒，千粒重显著下降。','一般减产10%–30%，严重时达70%–90%，甚至绝收。','农业防治为主：选用芒长口紧、抽穗整齐的抗虫品种，秋季深耕20 cm以上，与豆类等非禾本科作物轮作；化学防治关键在成虫期：小麦抽穗10%–20%和60%–70%时，用4.5%高效氯氰菊酯乳油1500倍液喷雾，早晚施药，间隔5–7天。','重','联网搜索','llm',0,'2026-11-02 06:27:23'),(61,'麦圆蜘蛛','penthaleus_major','小麦','虫害','成螨和若螨刺吸小麦叶片汁液，致叶片出现黄白色小斑点，严重时斑点连片呈灰白色或浅褐色，叶尖干枯卷曲，植株生长迟缓。','导致小麦矮化、分蘖减少、穗粒数下降，重度发生可造成减产30%以上，甚至全株枯死。','农业防治包括早春灌水、清除田边杂草；化学防治在返青至拔节期喷施1.8%阿维菌素乳油2000倍液或15%哒螨灵乳油3000倍液，重点喷施麦株中下部。','中','联网搜索','llm',0,'2026-11-02 06:27:30'),(62,'麦岩螨','longlegged_spider_mite','小麦','虫害','成螨和若螨吸食叶片汁液，致叶面出现密集黄白色小斑点，逐渐扩展为黄褐色至灰白色失绿斑块，严重时全叶干枯发红或呈锈色，叶背常可见细丝及活动螨体。','导致光合作用下降、植株早衰，严重时可造成小麦减产20%–40%。','农业防治：适时灌水降旱、清除田边杂草；生物防治：释放智利小植绥螨等捕食螨；药剂防治：于3月中下旬至4月上旬螨量达防治指标（单行30 cm≥200头）时，喷施2%阿维菌素乳油3000倍液，注意轮换使用哒螨灵或螺螨酯以延缓抗性。','中','联网搜索','llm',0,'2026-11-02 06:27:38'),(63,'麦茎蜂','wheat_sawfly','小麦','虫害','雌成虫用产卵器刺入小麦茎秆节间产卵，幼虫孵化后蛀食茎内组织，造成茎秆内部中空、易折断；受害植株常表现心叶萎蔫、茎秆弯曲或倒伏，拔起后可见茎内蛀道及白色幼虫。','导致穗部发育不良、籽粒不饱满，严重时整株枯死或倒伏，造成显著减产。','农业防治：适期播种、清除田间自生麦苗和杂草寄主；物理防治：成虫羽化盛期使用吸虫装置诱集；化学防治：在成虫盛发期喷施4.5%高效氯氰菊酯乳油1000–1500倍液，或2.5%溴氰菊酯乳油2000倍液。','中','联网搜索','llm',0,'2026-11-02 06:27:48'),(64,'麦黑斑潜叶蝇','cerodonta_denticornis','小麦','虫害','幼虫潜食叶肉形成弯曲虫道，导致叶片前半段出现淡褐色斑点或干枯；成虫在叶面产卵，卵孵化后幼虫即钻入叶肉为害。','影响光合作用，严重时致叶片干枯，降低产量。','成虫期可用80%敌敌畏乳油拌土撒施或4.5%高效氯氰菊酯喷雾；幼虫初发期选用1.8%阿维菌素、48%毒死蜱或40%氧化乐果喷雾。','中','联网搜索','llm',0,'2026-11-02 06:27:55'),(65,'甜菜潜叶蝇','beet_fly','甜菜','虫害','幼虫在叶片组织内潜食，形成宽而明显的蛇形或不规则潜道，表皮呈半透明水泡状；多头幼虫共害一叶时，潜道密集重叠，致叶片失绿、萎蔫甚至枯死。','严重降低光合作用，影响甜菜种株生长与种子产量，采种田被害率高时可导致减产10%–30%。','农业防治：清除田间残株、深翻灭蛹；物理防治：悬挂黄板诱杀成虫；化学防治：幼虫初发期喷施1.8%阿维菌素乳油2000倍液或25%灭幼脲悬浮剂1500倍液，7–10天1次，连防2次。','中','联网搜索','llm',0,'2026-11-02 06:28:02'),(66,'跳甲','flea_beetle','白菜','虫害','成虫啃食叶片幼嫩部位，造成密集椭圆形小孔，呈‘花脸’状；幼虫蛀食根部表皮及须根，致植株矮小、黄化、萎蔫，严重时整株枯死。','降低光合作用，影响商品价值；造成缺苗毁种；传播软腐病等土传病害，加重霜霉病、枯萎病等发生。','农业防治：轮作非十字花科作物、清洁田园、深翻晒土；物理防治：田间悬挂黄板诱杀；药剂防治：苗期喷雾选用噻虫嗪、联苯·噻虫胺或鱼藤酮，注意早晚施药并由田边向内围剿；地下幼虫可灌施辛硫磷。','重','联网搜索','llm',0,'2026-11-02 06:28:10'),(67,'菜青虫','cabbage_army_worm','白菜','虫害','幼虫啃食叶片，造成不规则孔洞和缺刻；高龄幼虫可将叶片吃光仅剩叶脉和叶柄；虫体青绿色，背有细黄线，体侧具一排小黄点；排泄粪便污染叶球，遇雨易诱发软腐病。','严重影响蔬菜产量与商品品质，伤口易引发细菌性软腐病等次生危害，严重时导致整株死亡。','农业防治：及时清园、深耕灭蛹、轮作葱蒜类；物理防治：覆盖50–60目防虫网；生物防治：2龄前喷施苏云金杆菌（Bt）；化学防治：可选用5%氯虫苯甲酰胺或1.8%阿维菌素+高效氯氟氰菊酯，重点喷施叶背及心叶。','重','联网搜索','llm',0,'2026-11-02 06:28:18'),(68,'甜菜夜蛾','beet_army_worm','玉米','虫害','初孵幼虫群集叶背取食叶肉，留下透明表皮呈“天窗”状；3龄后分散为害，啃食叶片成孔洞、缺刻，高龄幼虫暴食，可将整叶吃光，仅剩叶脉和叶柄；具假死性，受惊落地，昼伏夜出。','严重时导致作物光合面积锐减、生长受抑、产量显著下降，甚至绝收，尤以蔬菜和夏播作物受害突出。','抓住卵孵盛期至2–3龄幼虫期防治关键期，推荐使用20%甲维·茚虫威悬浮剂6–8毫升/亩，或10亿PIB/毫升甜菜夜蛾核型多角体病毒悬浮剂70–100毫升/亩，均匀喷雾，重点喷施叶背及地面，清晨或傍晚施药，连防2–3次，间隔5–7天。','重','联网搜索','llm',0,'2026-11-02 06:28:27'),(69,'草地螟','meadow_moth','甜菜','虫害','幼虫取食叶片，造成缺刻、孔洞，严重时将叶片吃光仅剩叶脉；高龄幼虫可蛀食嫩茎、花器和果实，田间可见网状残叶及虫粪。','导致作物光合能力下降、产量锐减，大发生时可造成绝收。','农业防治：及时清除田边地头灰菜等杂草寄主，减少产卵场所；化学防治：在幼虫3龄前喷施2%甲维盐乳油1000倍液或5%氯虫苯甲酰胺悬浮剂1500倍液，重点喷施田边及杂草丛生区。','重','联网搜索','llm',0,'2026-11-02 06:28:36'),(70,'东方绢金龟','sericaorient_alismots_chulsky','苹果','虫害','成虫傍晚至夜间活动，喜食果树及林木嫩叶，常将叶片啃食成缺刻或孔洞，严重时仅剩叶脉；幼虫（蛴螬）栖息于土壤中，咬食苗木和幼林根系，导致植株萎蔫、生长不良甚至死亡。','造成幼树叶片大量缺失，影响光合作用与树势；幼苗根系受损易倒伏枯死，春季造林期危害尤为突出。','农业防治：深耕翻土杀灭越冬幼虫；物理防治：利用趋光性设黑光灯诱杀成虫；药剂防治：幼虫期每亩用5%辛硫磷颗粒剂2–3公斤拌细土撒施，或成虫盛发期喷施2.5%高效氯氟氰菊酯乳油2000倍液。','重','联网搜索','llm',0,'2026-11-02 06:28:48'),(71,'苜蓿叶象甲','alfalfa_weevil','紫花苜蓿','虫害','成虫啃食叶片边缘，幼虫潜入叶肉取食形成不规则白色隧道，严重时叶片呈网状或仅剩叶脉，嫩茎和芽也可被蛀食。','导致苜蓿光合能力下降、产量锐减、品质恶化，严重田块可减产30%–70%，影响越冬和再生能力。','农业防治：适时刈割可清除大部分幼虫；生物防治：释放苜蓿叶象甲寄生蜂（如Triarthron pallidum）；化学防治：在幼虫孵化盛期喷施高效氯氟氰菊酯2.5%乳油2000倍液，注意轮换用药以延缓抗性。','重','联网搜索','llm',0,'2026-11-02 06:28:55'),(72,'苜蓿盲蝽','alfalfa_plant_bug','苜蓿','虫害','成虫和若虫刺吸植物嫩叶、花蕾、幼果汁液，导致叶片出现褪绿斑点、皱缩变形，花蕾枯萎脱落，幼铃（棉）或豆荚发育不良，严重时顶芽停止生长。','造成作物减产、品质下降，尤以蕾铃期受害对棉花产量影响显著。','农业防治：清除田边杂草、减少越冬寄主；物理防治：灯光诱杀成虫；化学防治：在若虫盛发初期喷施5%高效氯氟氰菊酯乳油1500倍液，或22%氟啶虫胺腈悬浮剂3000倍液，注意轮换用药以防抗性。','重','联网搜索','llm',0,'2026-11-02 06:29:05'),(73,'绿盲蝽','tarnished_plant_bug','棉花','虫害','成虫和若虫以刺吸式口器危害幼芽、嫩叶、花蕾及幼果，初期形成红褐色或黑色小斑点，随组织生长扩展为不规则孔洞（破叶疯）、叶片皱缩畸形；花蕾变黑脱落；幼果出现黑褐色锈斑、木栓化硬疤或隆起疱状坏死。','导致严重落花落果、叶片残缺、果实外观劣变，春茶减产超70%，枣园可致绝产，显著降低产量与商品价值。','农业防治：冬前清园、刮老翘皮、清除杂草及枯枝落叶；物理防治：悬挂黄板诱杀成虫；化学防治：在4月中下旬和9月回迁高峰期喷施2.5%联苯菊酯乳油2000倍液或0.3%苦参碱水剂800倍液，注意轮换用药并重点喷施嫩梢、叶背及树冠内膛。','重','联网搜索','llm',0,'2026-11-02 06:29:14'),(74,'红头芫菁','lytta_polita','玉米','虫害','成虫群聚取食叶片，造成叶片缺刻、孔洞甚至整株叶被吃光；幼虫在地下捕食竹蝗卵，不直接为害作物地上部分。','暴食性、群聚性强，可导致作物叶片严重损毁，影响光合作用和产量，对竹蝗生物防治功能具双重生态影响。','成虫盛发期（6月上中旬）采用植保无人机喷施2.5%高效氯氟氰菊酯乳油2000倍液，或40%水胺硫磷乳油1000倍液进行统防统治；辅以人工捕杀、深翻灭蛹。','重','联网搜索','llm',0,'2026-11-02 06:29:23'),(75,'豆芫菁','legume_blister_beetle','大豆','虫害','成虫群集取食豆科作物叶片，造成叶片缺刻、孔洞，严重时仅剩叶脉；幼虫栖息于土壤中，捕食蝗卵及昆虫卵，不直接危害作物地上部。','导致叶片光合面积减少，植株生长受抑，严重时影响结荚和产量。','农业防治：清除田边杂草、减少越冬场所；物理诱杀：利用黄色粘虫板或黑光灯诱杀成虫；化学防治：在成虫盛发期喷施2.5%溴氰菊酯乳油2000倍液或5%高效氯氟氰菊酯微乳剂1500倍液，注意避开蜜蜂活动期。','中','联网搜索','llm',0,'2026-11-02 06:29:31'),(76,'芫菁','blister_beetle','豆类','虫害','成虫群集取食叶片、花器及嫩茎，常将整株叶片啃食殆尽，留下叶脉呈网状；受害植株生长受抑，严重时整片田块光秃，可见明显沙沙取食声。','导致作物光合能力下降、落花落果、产量显著降低，严重时绝收。','农业防治：早春深翻灭蛹、人工捕杀成虫；药剂防治：在成虫盛发初期喷施2.5%溴氰菊酯乳油2000倍液或4.5%高效氯氰菊酯乳油1500倍液，重点喷施植株中上部及叶背。','中','联网搜索','llm',0,'2026-11-02 06:29:38'),(77,'苜蓿斑蚜','therioaphis_maculata_Buckton','苜蓿','虫害','成蚜和若蚜群集于苜蓿嫩茎、叶背及花序吸食汁液，致叶片卷缩、黄化、生长迟缓；严重时植株矮小、开花减少、豆荚畸形，蜜露诱发煤污病。','降低牧草产量与品质，影响种子结实率，削弱植株抗逆性。','农业防治：选用抗蚜品种（如HA-3）、适时刈割减少虫源；生物防治：保护利用瓢虫、草蛉、小花蝽等天敌；药剂防治：发生初期喷施10%吡虫啉可湿性粉剂2000倍液或25%噻虫嗪水分散粒剂3000倍液。','中','联网搜索','llm',0,'2026-11-02 06:29:45'),(78,'牛角花齿蓟马','odontothrips_loti','苜蓿','虫害','成虫及若虫以锉吸式口器危害植物幼嫩组织，导致叶片畸形、卷曲、硬化，嫩梢萎缩，花蕾发育不良，鲜草产量下降。','严重影响苜蓿产量与品质，降低饲用价值和商品性。','田间监测推荐使用黄色粘虫板诱捕；药剂防治可选用吡虫啉或啶虫脒喷雾，注意轮换用药以延缓抗性；结合清除田间杂草、覆盖地膜等农业措施。','重','联网搜索','llm',0,'2026-11-02 06:29:51'),(79,'蓟马','Thrips','黄瓜','虫害','成虫和若虫以锉吸式口器刮擦植物幼嫩组织表皮并吸食汁液，导致叶片出现银白色斑纹、卷曲、僵缩，花器畸形、落花，幼果表面锈斑、硬化、畸形，严重时植株生长停滞。','直接造成产量下降和商品价值丧失，并可传播番茄斑萎病毒等多种毁灭性植物病毒。','综合采用农业防治（清除杂草、清洁田园）、物理防治（悬挂蓝色粘虫板诱杀）和化学防治；推荐药剂包括多杀霉素、螺虫乙酯或20%呋虫胺，注意轮换用药以防抗性产生。','重','联网搜索','llm',0,'2026-11-02 06:29:59'),(80,'苜蓿籽蜂','alfalfa_seed_chalcid','紫花苜蓿','虫害','幼虫蛀食豆科植物种子，导致被害种子表面皱褶、空壳化；成虫体小黑色，雌蜂产卵器稍突出，卵具细长丝状柄，附着于种子表面。','种子被害率最高达30%，发芽率显著下降，影响牧草产量和品质。','可采用药剂拌种（如吡虫啉）、轮作及采收后干热处理（55℃维持12小时）等方法；注意在成虫羽化高峰期（5月下旬至8月中旬）加强监测与防控。','中','联网搜索','llm',0,'2026-11-02 06:30:05'),(81,'东方菜粉蝶','Pieris_canidia','白菜','虫害','幼虫啃食叶片，造成孔洞、缺刻，严重时仅剩叶脉和叶柄；高龄幼虫常群集为害，粪便污染叶球易诱发软腐病；成虫喜在叶背产卵，卵呈瓶状、淡黄至橙黄色。','导致蔬菜减产、品质下降，诱发软腐病等次生危害，影响商品价值。','农业防治：清洁田园、清除残株落叶及越冬蛹；生物防治：释放菜青虫颗粒体病毒（CPGV）；药剂防治：于卵孵化盛期喷施2.5%高效氯氟氰菊酯乳油2000倍液或16000 IU/mg苏云金杆菌可湿性粉剂1000倍液。','重','联网搜索','llm',0,'2026-11-02 06:30:13'),(82,'绿盲蝽','Apolygus_lucorum','棉花','虫害','成虫和若虫以刺吸式口器取食嫩芽、幼叶、花穗、幼果等幼嫩组织汁液，受害叶片初现红褐色小斑点，后扩展为不规则孔洞、皱缩畸形；幼果表面出现褐色锈斑、麻点、凹陷甚至裂果。','导致落花落果、叶片破损、果实畸形，严重时春茶减产超70%，葡萄大幅减产减收，品质严重下降。','坚持‘预防为主、综合防治’：清园灭卵、萌芽前喷3–5波美度石硫合剂；关键期（4月中下旬、谢花后至幼果期）傍晚喷施氟啶虫胺腈或联苯菊酯+吡蚜酮复配药剂，重点喷新梢、叶背及地面杂草。','重','联网搜索','llm',0,'2026-11-02 06:30:21'),(83,'刺蛾','Limacodidae','茶','虫害','幼虫取食叶片，低龄时啃食叶肉留下表皮呈半透明枯黄斑；高龄幼虫将叶片咬成平直缺刻，严重时仅剩叶脉甚至全叶被食光，部分种类还危害嫩枝和果实。','导致寄主植物光合能力下降、树势衰弱，影响果实产量与品质，严重时造成枝条枯死或整株衰败。','人工摘除虫茧及群集幼虫；保护利用瓢虫、小茧蜂等天敌；药剂防治可选用25%灭幼脲3号悬浮剂1500倍液、或5%高效氯氟氰菊酯微乳剂2000倍液，在幼虫3龄前喷雾，重点喷施叶背。','中','联网搜索','llm',0,'2026-11-02 06:30:30'),(84,'葡萄根瘤蚜','Viteus_vitifoliae','葡萄','虫害','成若虫刺吸葡萄根系汁液，须根端部膨大形成菱角状或鸟头状根瘤；主根及侧根形成关节形瘤或粗隆；美洲种葡萄叶背可形成粒状虫瘿。','根部维管束受损、皮层开裂腐烂，养分吸收受阻，树势衰弱、黄叶早落、产量锐减，严重时整株枯死。','严格检疫，禁从疫区调运苗木；选用抗性砧木（如‘和谐’‘5A’）嫁接；土壤处理可用50%辛硫磷500克拌细土50公斤，亩施25公斤；亦可用二硫化碳灌注。','重','联网搜索','llm',0,'2026-11-02 06:30:37'),(85,'葡萄缺节瘿螨','Colomerus_vitis','葡萄','虫害','成若螨刺吸叶片汁液，初期叶背形成苍白色斑，后期隆起产生白色至黑褐色毛毡状绒毛，导致叶片皱缩枯死；亦可侵染嫩梢、幼果、花梗和卷须。','严重时致叶片早衰脱落，光合能力下降，果实品质与产量降低，并可传播灰皮诺葡萄树病毒。','早春喷施波美3–5度石硫合剂；秋后清理病叶；生长季可选用螺螨酯、联苯肼酯、乙螨唑或阿维菌素等药剂防控，注意轮换用药以延缓抗性。','中','联网搜索','llm',0,'2026-11-02 06:30:43'),(86,'刘氏短须螨','Brevipoalpus_lewisi_McGregor','葡萄','虫害','成螨、若螨、幼螨多聚集于叶背主脉及侧脉附近刺吸汁液，致叶片出现油渍状斑块、卷曲、枯焦，严重时整叶失绿变褐。','影响光合作用，导致树势衰弱、早期落叶，降低观赏价值与果实产量。','冬季刮除老树皮消灭越冬雌螨；发生期喷施1.8%阿维菌素乳油1000倍液，或0.5%印楝素悬浮剂、0.3%苦参碱水剂；可结合释放天敌尼氏钝绥螨进行生物防治。','中','联网搜索','llm',0,'2026-11-02 06:30:51'),(87,'葡萄十星叶甲','oides_decempunctata','葡萄','虫害','成虫和幼虫均取食叶片，造成叶片出现孔洞、缺刻或网状枯黄；发生严重时叶肉被食尽，仅残留叶脉及绒毛；幼虫体背具黑斑，老熟后入土化蛹。','导致光合作用严重受阻，树势衰弱，影响果实品质与产量，严重时可致植株早衰。','清除田间枯枝落叶和杂草，人工捕捉具假死性的成虫及幼虫；药剂防治可选用50%敌敌畏乳油1000倍液或4.5%高效氯氰菊酯乳油1500倍液均匀喷雾，重点喷施叶背。','重','联网搜索','llm',0,'2026-11-02 06:30:58'),(88,'茶黄螨','Polyphagotars_onemus_latus','辣椒','虫害','雌成螨体长约0.21毫米，淡黄至黄绿色，半透明有光泽；主要刺吸嫩叶、花蕾、幼果汁液，致叶片变厚、僵直、向背面卷曲，嫩叶皱缩畸形，花蕾枯死，果实变褐色、粗糙、无光泽、易裂果。','导致植株矮缩、落花落果，严重时整株衰弱甚至死亡，显著降低产量与品质。','可选用22.4%螺虫乙酯悬浮剂2000–3000倍液、1.3%苦参碱水剂或5.7%甲氨基阿维菌素苯甲酸盐水分散粒剂4000–6000倍液喷雾防治，重点喷施植株上部嫩叶背面及生长点。','重','联网搜索','llm',0,'2026-11-02 06:31:06'),(89,'康氏粉蚧','Pseudococcus_comstocki_Kuwana','苹果','虫害','若虫和雌成虫刺吸芽、叶、果实、枝条及根部汁液；嫩枝和根部受害常肿胀纵裂枯死；幼果受害易畸形；排泄蜜露诱发煤污病，影响光合作用。','导致树势衰弱、果实品质下降、产量减少，严重时可致枝干枯死。','加强果园清洁与冬季清园；春季萌芽前喷施3～5波美度石硫合剂；若虫盛发期可选用25%噻嗪酮可湿性粉剂1000倍液或22.4%螺虫乙酯悬浮剂4000倍液均匀喷雾。','重','联网搜索','llm',0,'2026-11-02 06:31:14'),(90,'葡萄透翅蛾','parathrene_regalis','葡萄','虫害','幼虫蛀食葡萄嫩梢、枝蔓髓部及穗轴，被害部位肿大呈瘤状，表皮变褐开裂，叶片黄化脱落，枝蔓易折断枯死，蛀道内充满褐色虫粪和木屑。','导致树势衰弱、产量下降，严重时整枝枯死，影响多年结果能力。','农业防治：结合冬剪彻底剪除受害枝蔓并烧毁；物理防治：成虫羽化期（6月上旬至7月中旬）悬挂性诱剂或黑光灯诱杀；药剂防治：幼虫孵化盛期喷施2.5%高效氯氟氰菊酯乳油2000倍液，重点喷布新梢基部及枝蔓分叉处。','重','联网搜索','llm',0,'2026-11-02 06:31:21'),(91,'葡萄天蛾','Ampelophaga','葡萄','虫害','幼虫取食叶片，造成缺刻与孔洞；高龄幼虫仅残留叶柄，严重时可将整株叶片食光；受惊扰时分泌绿色液体。','导致光合作用减弱，树势衰退，果实品质下降，影响葡萄产量与商品等级。','成虫期用黑光灯或糖醋液诱杀；结合夏剪人工捕杀幼虫；秋施基肥时深翻树盘土壤灭蛹；幼虫初发期喷施25克/升溴氰菊酯乳油2000–2500倍液。','中','联网搜索','llm',0,'2026-11-02 06:31:27'),(92,'斑衣蜡蝉','Lycorma_delicatula','臭椿','虫害','成虫和若虫以刺吸式口器吸食嫩梢、叶片及枝干汁液，造成叶片穿孔、皱缩、嫩梢萎蔫畸形；排泄大量蜜露，诱发煤污病，覆盖叶面影响光合作用。','削弱树势，导致果实品质下降、减产，严重时引起枝干枯裂甚至整株死亡。','农业防治：冬季刮除或刷除卵块；物理防治：黑光灯诱杀成虫；化学防治：低龄若虫盛发期喷施10%吡虫啉可湿性粉剂2000倍液，或2.5%高效氯氟氰菊酯乳油3000倍液。','重','联网搜索','llm',0,'2026-11-02 06:31:35'),(93,'盲蝽','Miridae','棉花','虫害','成虫和若虫以刺吸式口器危害植物幼嫩组织，导致叶片出现黄褐色斑点、皱缩、卷曲、畸形，顶芽枯萎，花器脱落，幼果僵化或形成硬疤，豆荚发育不良。','严重时可致作物减产50%，影响种子产量与品质，并威胁多种经济作物安全生产。','农业防治（清除田边杂草、轮作）；物理防治（灯光诱杀、性诱捕器）；化学防治：选用4.5%高效氯氰菊酯乳油2000倍液、10%吡虫啉可湿性粉剂1500倍液或1.8%阿维菌素乳油2500倍液，于早晚喷雾，重点覆盖叶背及茎基部。','重','联网搜索','llm',0,'2026-11-02 06:31:49'),(94,'温室白粉虱','Trialeurodes_vaporariorum','黄瓜','虫害','成虫和若虫群集于叶片背面刺吸汁液，导致叶片褪绿、黄化、萎蔫；分泌大量蜜露覆盖叶面，诱发煤污病，影响光合作用；还可传播多种植物病毒。','严重降低作物产量与商品价值，引发煤污病和病毒病流行，造成大面积减产甚至绝收。','农业防治：清除残株、黄板诱杀成虫；生物防治：释放丽蚜小蜂；化学防治：可选用25%噻虫嗪水分散粒剂3000倍液或10%溴氰虫酰胺悬浮剂2000倍液喷雾，重点喷施叶背，7–10天1次，连防2–3次。','重','联网搜索','llm',0,'2026-11-02 06:31:57'),(95,'葡萄斑叶蝉','Erythroneura_apicalis','葡萄','虫害','成虫和若虫群集叶背刺吸汁液，受害叶片正面出现橙黄色或黄白色褪绿斑点，严重时整叶失绿苍白、卷曲，叶背可见虫体及少量分泌物。','导致光合作用下降、叶片早衰脱落，削弱树势，影响果实品质与产量。','可选用1.3%苦参碱水剂、50%啶虫脒水分散粒剂或0.8%阿维·印楝素乳油喷雾防治，重点喷施叶背，结合黄板诱杀与清园除草等农业措施。','中','联网搜索','llm',0,'2026-11-02 06:32:04'),(96,'柑橘凤蝶','Papilio_xuthus','柑橘','虫害','幼虫取食嫩芽、嫩叶，造成叶片出现孔洞、缺刻，严重时将叶片吃光，仅残留叶柄或主脉；老熟幼虫体长38～48mm，黄绿色，具橙黄色翻缩腺和眼斑。','导致植株光合能力下降，树势衰弱，影响果实产量与品质。','人工摘除卵块及低龄幼虫；生物防治可释放赤眼蜂；药剂防治可在幼虫3龄前喷施2.5%溴氰菊酯乳油2000倍液或20%氰戊菊酯乳油3000倍液。','中','联网搜索','llm',0,'2026-11-02 06:32:11'),(97,'柑橘红蜘蛛','Panonchus_citri_McGregor','柑橘','虫害','成螨、若螨、幼螨群集于叶片、嫩梢、果实及花蕾上