DROP TABLE IF EXISTS `t_model`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_model` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `model_name` varchar(100) NOT NULL COMMENT '模型名称（可重命名）',
  `file_name` varchar(200) NOT NULL COMMENT '原始文件名',
  `file_path` varchar(255) NOT NULL COMMENT '模型文件相对路径',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小（字节）',
  `class_num` int DEFAULT '30' COMMENT '识别类别数量',
  `version` varchar(50) DEFAULT NULL COMMENT '版本号',
  `description` varchar(500) DEFAULT NULL COMMENT '模型描述',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认模型：1是 0否',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `upload_user_id` int DEFAULT NULL COMMENT '上传人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='YOLO模型表';
