--
-- Table structure for table `t_oper_log`
--

DROP TABLE IF EXISTS `t_oper_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_oper_log` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int DEFAULT NULL COMMENT '操作用户ID',
  `username` varchar(50) DEFAULT NULL COMMENT '用户名',
  `module` varchar(50) DEFAULT NULL COMMENT '功能模块',
  `oper_type` varchar(20) DEFAULT NULL COMMENT '操作类型：新增/修改/删除/查询/导出/识别',
  `request_url` varchar(200) DEFAULT NULL COMMENT '请求地址',
  `params` varchar(1000) DEFAULT NULL COMMENT '请求参数摘要',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '操作结果：1成功 0失败',
  `cost_ms` int DEFAULT '0' COMMENT '耗时毫秒',
  `oper_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='操作日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

