DROP TABLE IF EXISTS `t_pesticide`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_pesticide` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL COMMENT '药剂通用名（已剥离剂型/前缀）',
  `formulation` varchar(40) DEFAULT NULL COMMENT '剂型：乳油/可湿性粉剂/悬浮剂等',
  `crops` varchar(200) DEFAULT NULL COMMENT '适用作物，顿号分隔',
  `dosage` varchar(200) DEFAULT NULL COMMENT '用法用量',
  `safety_interval` varchar(60) DEFAULT NULL COMMENT '安全间隔期',
  `note` text COMMENT '备注/原文',
  `filled_by` varchar(20) DEFAULT NULL COMMENT 'llm / manual',
  `verified` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='药剂表';
/*!40101 SET character_set_client = @saved_cs_client */;

