INSERT INTO `t_pesticide` VALUES (1,'石硫合剂',NULL,'苹果','3–5波美度',NULL,'清除病叶落叶并深埋；萌芽前喷施石硫合剂；发病初期选用戊唑醇、苯醚甲环唑等药剂交替喷雾，注意雨后补喷。','llm',0,'2026-11-02 06:56:32'),(2,'戊唑醇',NULL,'苹果',NULL,NULL,'清除病叶落叶并深埋；萌芽前喷施石硫合剂；发病初期选用戊唑醇、苯醚甲环唑等药剂交替喷雾，注意雨后补喷。','llm',0,'2026-11-02 06:56:32'),(3,'苯醚甲环唑',NULL,'苹果',NULL,NULL,'清除病叶落叶并深埋；萌芽前喷施石硫合剂；发病初期选用戊唑醇、苯醚甲环唑等药剂交替喷雾，注意雨后补喷。','llm',0,'2026-11-02 06:56:32'),(4,'三唑酮',NULL,'苹果',NULL,NULL,'果园远离或清除转主寄主柏树；萌芽期喷保护性杀菌剂；发病初期用三唑酮、氟硅唑等防治。','llm',0,'2026-11-02 06:56:35'),(5,'氟硅唑',NULL,'苹果',NULL,NULL,'果园远离或清除转主寄主柏树；萌芽期喷保护性杀菌剂；发病初期用三唑酮、氟硅唑等防治。','llm',0,'2026-11-02 06:56:35'),(6,'代森锰锌',NULL,'甜椒',NULL,NULL,'选用抗病品种；避免连作；发病初期喷施代森锰锌、苯醚甲环唑等药剂，及时摘除病叶。','llm',0,'2026-11-02 06:56:39'),(7,'吡唑醚菌酯',NULL,'玉米',NULL,NULL,'选用抗病品种；合理轮作；抽雄前后喷施吡唑醚菌酯、苯醚甲环唑等药剂。','llm',0,'2026-11-02 06:56:55'),(8,'嘧菌酯',NULL,'玉米',NULL,NULL,'种植抗病品种；清除田间病残体；发病初期喷施戊唑醇、嘧菌酯等，适当早播避病。','llm',0,'2026-11-02 06:56:57'),(9,'烯唑醇',NULL,'玉米',NULL,NULL,'选用抗锈品种；合理密植与施肥；发病初期喷三唑酮、烯唑醇等。','llm',0,'2026-11-02 06:56:59'),(10,'烯酰吗啉',NULL,'马铃薯',NULL,NULL,'使用脱毒种薯；监测预警后及时喷施烯酰吗啉、氟啶胺等；发现中心病株立即拔除。','llm',0,'2026-11-02 06:57:06'),(11,'氟啶胺',NULL,'马铃薯',NULL,NULL,'使用脱毒种薯；监测预警后及时喷施烯酰吗啉、氟啶胺等；发现中心病株立即拔除。','llm',0,'2026-11-02 06:57:06'),(12,'醚菌酯',NULL,'南瓜',NULL,NULL,'降低田间湿度、改善通风；发病初期喷施醚菌酯、腈菌唑或小苏打溶液，严重时摘除病叶。','llm',0,'2026-11-02 06:57:12'),(13,'腈菌唑',NULL,'南瓜',NULL,NULL,'降低田间湿度、改善通风；发病初期喷施醚菌酯、腈菌唑或小苏打溶液，严重时摘除病叶。','llm',0,'2026-11-02 06:57:12'),(14,'小苏打',NULL,'南瓜',NULL,NULL,'降低田间湿度、改善通风；发病初期喷施醚菌酯、腈菌唑或小苏打溶液，严重时摘除病叶。','llm',0,'2026-11-02 06:57:12'),(15,'百菌清',NULL,'番茄',NULL,NULL,'避免连作；滴灌降低叶面湿度；喷施百菌清、嘧菌酯等保护与治疗药剂。','llm',0,'2026-11-02 06:57:18'),(16,'春雷霉素',NULL,'番茄',NULL,NULL,'使用无病种子；避免叶面长时间潮湿；发病初期喷春雷霉素、铜制剂，注意与真菌病害区分。','llm',0,'2026-11-02 06:57:21'),(17,'铜制剂',NULL,'番茄',NULL,NULL,'使用无病种子；避免叶面长时间潮湿；发病初期喷春雷霉素、铜制剂，注意与真菌病害区分。','llm',0,'2026-11-02 06:57:21'),(18,'霜脲氰',NULL,'番茄',NULL,NULL,'选用抗病品种；夜间降湿；发现中心病株立即喷烯酰吗啉、霜脲氰等，并摘除病叶。','llm',0,'2026-11-02 06:57:23'),(19,'春雷·王铜',NULL,'番茄',NULL,NULL,'加强通风排湿；合理密植；喷施嘧菌酯、春雷·王铜等，摘除下部病叶。','llm',0,'2026-11-02 06:57:28'),(20,'阿维菌素',NULL,'番茄','15–20克/亩',NULL,'保持田间湿度；释放捕食螨；点片发生时选用阿维菌素、联苯肼酯等轮换用药。','llm',0,'2026-11-02 06:57:30'),(21,'联苯肼酯',NULL,'番茄',NULL,NULL,'保持田间湿度；释放捕食螨；点片发生时选用阿维菌素、联苯肼酯等轮换用药。','llm',0,'2026-11-02 06:57:30'),(22,'毒死蜱','乳油','水稻','60–80毫升/亩',NULL,'抓住2–3龄幼虫关键期施药，推荐使用1.8%阿维菌素乳油15–20克/亩，或45%毒死蜱乳油60–80毫升/亩，兑水50公斤均匀喷雾，连防2–3次，间隔5–7天。','llm',0,'2026-11-02 06:57:37'),(23,'敌百虫','晶体','水稻','800倍液',NULL,'农业防治：及时清除田边杂草、处理稻茬；物理防治：灯光诱杀成虫；生物防治：释放赤眼蜂寄生卵块；化学防治：在低龄幼虫期喷施90%敌百虫晶体800倍液或25%杀虫双水剂500倍液。','llm',0,'2026-11-02 06:57:39'),(24,'杀虫双','水剂','水稻','500倍液',NULL,'农业防治：及时清除田边杂草、处理稻茬；物理防治：灯光诱杀成虫；生物防治：释放赤眼蜂寄生卵块；化学防治：在低龄幼虫期喷施90%敌百虫晶体800倍液或25%杀虫双水剂500倍液。','llm',0,'2026-11-02 06:57:39'),(25,'吡虫啉','可湿性粉剂','水稻','喷施',NULL,'铲除田边禾本科杂草以减少越冬虫源；培育壮苗带药移栽；药剂防治可选用10%吡虫啉可湿性粉剂、70%吡虫啉+氯虫苯甲酰胺、1.8%阿维菌素或1%甲维盐喷雾。','llm',0,'2026-11-02 06:57:43'),(26,'吡虫啉+氯虫苯甲酰胺',NULL,'水稻',NULL,NULL,'铲除田边禾本科杂草以减少越冬虫源；培育壮苗带药移栽；药剂防治可选用10%吡虫啉可湿性粉剂、70%吡虫啉+氯虫苯甲酰胺、1.8%阿维菌素或1%甲维盐喷雾。','llm',0,'2026-11-02 06:57:43'),(27,'甲维盐',NULL,'水稻','3000倍液',NULL,'铲除田边禾本科杂草以减少越冬虫源；培育壮苗带药移栽；药剂防治可选用10%吡虫啉可湿性粉剂、70%吡虫啉+氯虫苯甲酰胺、1.8%阿维菌素或1%甲维盐喷雾。','llm',0,'2026-11-02 06:57:43'),(28,'四氯虫酰胺',NULL,'水稻',NULL,NULL,'抓住卵孵化盛期至低龄幼虫高峰期施药；推荐使用四氯虫酰胺、乙多·甲氧虫、或短稳杆菌等交替轮换用药，避免长期单一使用氯虫苯甲酰胺等已产生高水平抗性的药剂。','llm',0,'2026-11-02 06:57:46'),(29,'乙多·甲氧虫',NULL,'水稻',NULL,NULL,'抓住卵孵化盛期至低龄幼虫高峰期施药；推荐使用四氯虫酰胺、乙多·甲氧虫、或短稳杆菌等交替轮换用药，避免长期单一使用氯虫苯甲酰胺等已产生高水平抗性的药剂。','llm',0,'2026-11-02 06:57:47'),(30,'短稳杆菌',NULL,'水稻',NULL,NULL,'抓住卵孵化盛期至低龄幼虫高峰期施药；推荐使用四氯虫酰胺、乙多·甲氧虫、或短稳杆菌等交替轮换用药，避免长期单一使用氯虫苯甲酰胺等已产生高水平抗性的药剂。','llm',0,'2026-11-02 06:57:47'),(31,'氯虫苯甲酰胺',NULL,'水稻','幼虫3龄前喷施',NULL,'农业防治：冬闲田灌水灭蛹、及时处理稻桩；生物防治：释放赤眼蜂；化学防治：在卵孵高峰期喷施氯虫苯甲酰胺、阿维·氯苯酰或杀虫双，注意轮换用药以延缓抗性。','llm',0,'2026-11-02 06:57:50'),(32,'阿维·氯苯酰',NULL,'水稻',NULL,NULL,'农业防治：冬闲田灌水灭蛹、及时处理稻桩；生物防治：释放赤眼蜂；化学防治：在卵孵高峰期喷施氯虫苯甲酰胺、阿维·氯苯酰或杀虫双，注意轮换用药以延缓抗性。','llm',0,'2026-11-02 06:57:50'),(33,'三唑磷','乳油','水稻','喷施',NULL,'在成虫盛发期至卵孵化高峰期，亩用5%毒死蜱颗粒剂1.5–1.8公斤拌适量干细土或肥料撒施；也可喷施吡虫啉或三唑磷乳油。注意保持田间水层5–7天，并避免高温中午施药。','llm',0,'2026-11-02 06:57:53'),(34,'阿维·三唑磷','乳油','水稻','50毫升/亩',NULL,'防治适期为成虫盛发期和卵孵高峰期（如5月中旬、7月上中旬）；可选用20%阿维·三唑磷乳油50毫升/亩、或1.8%阿维菌素40–80毫升/亩、或80%敌敌畏乳油1000倍液喷雾，施药时保持3–5厘米浅水层。','llm',0,'2026-11-02 06:57:57'),(35,'敌敌畏','乳油','水稻','1000倍液喷雾',NULL,'防治适期为成虫盛发期和卵孵高峰期（如5月中旬、7月上中旬）；可选用20%阿维·三唑磷乳油50毫升/亩、或1.8%阿维菌素40–80毫升/亩、或80%敌敌畏乳油1000倍液喷雾，施药时保持3–5厘米浅水层。','llm',0,'2026-11-02 06:57:57'),(36,'吡蚜酮','悬浮剂','水稻','20–30克/亩',NULL,'加强田间监测，孕穗至抽穗期为重点防治期；药剂可选用25%吡蚜酮悬浮剂20–30克/亩、或10%烯啶虫胺水剂30–40毫升/亩，兑水喷雾，注意轮换用药以防抗性；结合合理肥水管理，避免偏施氮肥。','llm',0,'2026-11-02 06:58:00'),(37,'烯啶虫胺','水剂','水稻','30–40毫升/亩',NULL,'加强田间监测，孕穗至抽穗期为重点防治期；药剂可选用25%吡蚜酮悬浮剂20–30克/亩、或10%烯啶虫胺水剂30–40毫升/亩，兑水喷雾，注意轮换用药以防抗性；结合合理肥水管理，避免偏施氮肥。','llm',0,'2026-11-02 06:58:00'),(38,'噻嗪酮','可湿性粉剂','水稻','50克/亩',NULL,'在低龄若虫高峰期施药，每亩用70%吡虫啉水分散粒剂2–4克，或25%噻嗪酮可湿性粉剂50克，加水50千克均匀喷雾于茎叶基部。','llm',0,'2026-11-02 06:58:03'),(39,'呋虫胺',NULL,'水稻',NULL,NULL,'农业防治包括选用抗（耐）虫品种、清除田边禾本科杂草、合理肥水管理；化学防治在低龄若虫高峰期喷施吡蚜酮、烯啶虫胺或呋虫胺，注意轮换用药以防抗性。','llm',0,'2026-11-02 06:58:06'),(40,'氯虫·噻虫嗪','悬浮剂','水稻',NULL,NULL,'坚持‘早发现、早防治’，推行带药移栽（如用30%氯虫·噻虫嗪悬浮剂浸秧根）、本田期喷施40%毒死蜱乳油或20%呋虫胺可溶粒剂；结合翻耕灭茬、清除田边杂草、灯光诱杀及严格检疫。','llm',0,'2026-11-02 06:58:10'),(41,'叶蝉散','可湿性粉剂','水稻','500倍液',NULL,'清除田边杂草及冬闲田寄主，灯光诱杀成虫；重点在秧田期和分蘖初期喷药防治，可选用10%吡虫啉可湿性粉剂1500倍液或25%叶蝉散可湿性粉剂500倍液均匀喷雾。','llm',0,'2026-11-02 06:58:12'),(42,'辛硫磷','颗粒剂','玉米','1.5–2 kg/亩拌土沟施',NULL,'农业防治：深耕晒垡、轮作倒茬、清除田间杂草和秸秆；物理诱杀：灯光诱杀成虫；药剂防治：播种前用3%辛硫磷颗粒剂1.5–2 kg/亩拌土沟施，或苗期用50%辛硫磷乳油1000倍液灌根。','llm',0,'2026-11-02 06:58:18'),(43,'抑太保','乳油','大豆','2000倍液',NULL,'农业防治：清除田间枯枝落叶、翻耕灭蛹；物理防治：黑光灯诱杀成虫；生物防治：喷施Bt制剂或青虫菌粉剂（100亿孢子/g，1500倍液）；化学防治：低龄幼虫期喷施5%抑太保乳油2000倍液或50%马拉硫磷乳油1000倍液，间隔7–10天，连防1–2次。','llm',0,'2026-11-02 06:58:28'),(44,'马拉硫磷','乳油','大豆','1000倍液',NULL,'农业防治：清除田间枯枝落叶、翻耕灭蛹；物理防治：黑光灯诱杀成虫；生物防治：喷施Bt制剂或青虫菌粉剂（100亿孢子/g，1500倍液）；化学防治：低龄幼虫期喷施5%抑太保乳油2000倍液或50%马拉硫磷乳油1000倍液，间隔7–10天，连防1–2次。','llm',0,'2026-11-02 06:58:28'),(45,'Bt制剂',NULL,'大豆','1500倍液',NULL,'农业防治：清除田间枯枝落叶、翻耕灭蛹；物理防治：黑光灯诱杀成虫；生物防治：喷施Bt制剂或青虫菌粉剂（100亿孢子/g，1500倍液）；化学防治：低龄幼虫期喷施5%抑太保乳油2000倍液或50%马拉硫磷乳油1000倍液，间隔7–10天，连防1–2次。','llm',0,'2026-11-02 06:58:28'),(46,'青虫菌粉剂','粉剂','大豆','1500倍液',NULL,'农业防治：清除田间枯枝落叶、翻耕灭蛹；物理防治：黑光灯诱杀成虫；生物防治：喷施Bt制剂或青虫菌粉剂（100亿孢子/g，1500倍液）；化学防治：低龄幼虫期喷施5%抑太保乳油2000倍液或50%马拉硫磷乳油1000倍液，间隔7–10天，连防1–2次。','llm',0,'2026-11-02 06:58:28'),(47,'高效氯氟氰菊酯','乳油','棉花','2000倍液',NULL,'农业防治：深耕灭蛹、清除杂草、诱杀成虫（糖醋液或黑光灯）；化学防治：幼虫3龄前喷施2.5%高效氯氟氰菊酯乳油2000倍液，或5%氯虫苯甲酰胺悬浮剂1500倍液，重点喷洒苗基部及周围土壤。','llm',0,'2026-11-02 06:58:31'),(48,'溴氰菊酯','乳油','烟草','3000 倍液',NULL,'早春清除田边杂草并沤肥处理；1–3龄幼虫期喷施90%晶体敌百虫800倍液或2.5%溴氰菊酯3000倍液；成虫期可用黑光灯或糖醋液（糖:醋:白酒:水=6:3:1:10，加90%敌百虫1份）诱杀。','llm',0,'2026-11-02 06:58:35'),(49,'哒螨灵',NULL,'豇豆','3000倍液',NULL,'农业防治：轮作、清除田间杂草与枯枝落叶；生物防治：释放捕食螨、瓢虫等天敌；化学防治：喷施阿维菌素、联苯肼酯或哒螨灵，注意轮换用药以延缓抗性。','llm',0,'2026-11-02 06:58:41'),(50,'喹硫磷','乳油','玉米','150毫升/亩',NULL,'心叶末期喷施25%喹硫磷乳油150毫升/亩，或1%甲维盐乳油1500倍液；结合农业防治（秸秆粉碎还田或清烧）、释放赤眼蜂、性信息素诱杀及去雄等综合措施。','llm',0,'2026-11-02 06:58:43'),(51,'除虫脲',NULL,'桃',NULL,NULL,'成虫期可布设性诱捕器或杀虫灯诱杀；幼果期及时套袋阻隔产卵；药剂防治宜在成虫盛发期及产卵高峰期喷施氯虫苯甲酰胺、吡虫啉或除虫脲等高效低毒药剂。','llm',0,'2026-11-02 06:58:52'),(52,'噻虫嗪','水分散粒剂','小麦','3000倍液',NULL,'农业防治结合药剂防治：及时清除田边杂草，选用抗蚜品种；发生初期喷施10%吡虫啉可湿性粉剂2000倍液或25%噻虫嗪水分散粒剂3000倍液，注意轮换用药以防抗性。','llm',0,'2026-11-02 06:58:58'),(53,'抗蚜威','可湿性粉剂','小麦','3000倍液',NULL,'农业防治：适期播种、清除田边杂草寄主；生物防治：保护瓢虫、草蛉、蚜茧蜂等天敌；化学防治：在蚜量达防治指标时喷施10%吡虫啉可湿性粉剂（2000倍液）或25%抗蚜威可湿性粉剂（3000倍液），注意轮换用药以延缓抗性发展。','llm',0,'2026-11-02 06:59:03'),(54,'高效氯氰菊酯','乳油','小麦','1500倍液喷雾',NULL,'农业防治为主：选用芒长口紧、抽穗整齐的抗虫品种，秋季深耕20 cm以上，与豆类等非禾本科作物轮作；化学防治关键在成虫期：小麦抽穗10%–20%和60%–70%时，用4.5%高效氯氰菊酯乳油1500倍液喷雾，早晚施药，间隔5–7天。','llm',0,'2026-11-02 06:59:05'),(55,'螺螨酯',NULL,'小麦',NULL,NULL,'农业防治：适时灌水降旱、清除田边杂草；生物防治：释放智利小植绥螨等捕食螨；药剂防治：于3月中下旬至4月上旬螨量达防治指标（单行30 cm≥200头）时，喷施2%阿维菌素乳油3000倍液，注意轮换使用哒螨灵或螺螨酯以延缓抗性。','llm',0,'2026-11-02 06:59:11'),(56,'氧化乐果',NULL,'小麦',NULL,NULL,'成虫期可用80%敌敌畏乳油拌土撒施或4.5%高效氯氰菊酯喷雾；幼虫初发期选用1.8%阿维菌素、48%毒死蜱或40%氧化乐果喷雾。','llm',0,'2026-11-02 06:59:19'),(57,'灭幼脲','悬浮剂','甜菜','1500倍液',NULL,'农业防治：清除田间残株、深翻灭蛹；物理防治：悬挂黄板诱杀成虫；化学防治：幼虫初发期喷施1.8%阿维菌素乳油2000倍液或25%灭幼脲悬浮剂1500倍液，7–10天1次，连防2次。','llm',0,'2026-11-02 06:59:22'),(58,'联苯·噻虫胺',NULL,'白菜',NULL,NULL,'农业防治：轮作非十字花科作物、清洁田园、深翻晒土；物理防治：田间悬挂黄板诱杀；药剂防治：苗期喷雾选用噻虫嗪、联苯·噻虫胺或鱼藤酮，注意早晚施药并由田边向内围剿；地下幼虫可灌施辛硫磷。','llm',0,'2026-11-02 06:59:26'),(59,'鱼藤酮',NULL,'白菜',NULL,NULL,'农业防治：轮作非十字花科作物、清洁田园、深翻晒土；物理防治：田间悬挂黄板诱杀；药剂防治：苗期喷雾选用噻虫嗪、联苯·噻虫胺或鱼藤酮，注意早晚施药并由田边向内围剿；地下幼虫可灌施辛硫磷。','llm',0,'2026-11-02 06:59:26'),(60,'苏云金杆菌',NULL,'白菜','1000倍液',NULL,'农业防治：及时清园、深耕灭蛹、轮作葱蒜类；物理防治：覆盖50–60目防虫网；生物防治：2龄前喷施苏云金杆菌（Bt）；化学防治：可选用5%氯虫苯甲酰胺或1.8%阿维菌素+高效氯氟氰菊酯，重点喷施叶背及心叶。','llm',0,'2026-11-02 06:59:30'),(61,'甲维·茚虫威','悬浮剂','玉米','6–8毫升/亩',NULL,'抓住卵孵盛期至2–3龄幼虫期防治关键期，推荐使用20%甲维·茚虫威悬浮剂6–8毫升/亩，或10亿PIB/毫升甜菜夜蛾核型多角体病毒悬浮剂70–100毫升/亩，均匀喷雾，重点喷施叶背及地面，清晨或傍晚施药，连防2–3次，间隔5–7天。','llm',0,'2026-11-02 06:59:33'),(62,'甜菜夜蛾核型多角体病毒','悬浮剂','玉米','70–100毫升/亩',NULL,'抓住卵孵盛期至2–3龄幼虫期防治关键期，推荐使用20%甲维·茚虫威悬浮剂6–8毫升/亩，或10亿PIB/毫升甜菜夜蛾核型多角体病毒悬浮剂70–100毫升/亩，均匀喷雾，重点喷施叶背及地面，清晨或傍晚施药，连防2–3次，间隔5–7天。','llm',0,'2026-11-02 06:59:33'),(63,'氟啶虫胺腈','悬浮剂','苜蓿','3000倍液',NULL,'农业防治：清除田边杂草、减少越冬寄主；物理防治：灯光诱杀成虫；化学防治：在若虫盛发初期喷施5%高效氯氟氰菊酯乳油1500倍液，或22%氟啶虫胺腈悬浮剂3000倍液，注意轮换用药以防抗性。','llm',0,'2026-11-02 06:59:43'),(64,'联苯菊酯','乳油','棉花','2000倍液',NULL,'农业防治：冬前清园、刮老翘皮、清除杂草及枯枝落叶；物理防治：悬挂黄板诱杀成虫；化学防治：在4月中下旬和9月回迁高峰期喷施2.5%联苯菊酯乳油2000倍液或0.3%苦参碱水剂800倍液，注意轮换用药并重点喷施嫩梢、叶背及树冠内膛。','llm',0,'2026-11-02 06:59:46'),(65,'苦参碱','水剂','棉花','800倍液',NULL,'农业防治：冬前清园、刮老翘皮、清除杂草及枯枝落叶；物理防治：悬挂黄板诱杀成虫；化学防治：在4月中下旬和9月回迁高峰期喷施2.5%联苯菊酯乳油2000倍液或0.3%苦参碱水剂800倍液，注意轮换用药并重点喷施嫩梢、叶背及树冠内膛。','llm',0,'2026-11-02 06:59:46'),(66,'水胺硫磷','乳油','玉米','1000 倍液',NULL,'成虫盛发期（6月上中旬）采用植保无人机喷施2.5%高效氯氟氰菊酯乳油2000倍液，或40%水胺硫磷乳油1000倍液进行统防统治；辅以人工捕杀、深翻灭蛹。','llm',0,'2026-11-02 06:59:49'),(67,'啶虫脒',NULL,'苜蓿',NULL,NULL,'田间监测推荐使用黄色粘虫板诱捕；药剂防治可选用吡虫啉或啶虫脒喷雾，注意轮换用药以延缓抗性；结合清除田间杂草、覆盖地膜等农业措施。','llm',0,'2026-11-02 07:00:00'),(68,'多杀霉素',NULL,'黄瓜',NULL,NULL,'综合采用农业防治（清除杂草、清洁田园）、物理防治（悬挂蓝色粘虫板诱杀）和化学防治；推荐药剂包括多杀霉素、螺虫乙酯或20%呋虫胺，注意轮换用药以防抗性产生。','llm',0,'2026-11-02 07:00:03'),(69,'螺虫乙酯',NULL,'黄瓜','2000–3000倍液',NULL,'综合采用农业防治（清除杂草、清洁田园）、物理防治（悬挂蓝色粘虫板诱杀）和化学防治；推荐药剂包括多杀霉素、螺虫乙酯或20%呋虫胺，注意轮换用药以防抗性产生。','llm',0,'2026-11-02 07:00:03'),(70,'灭幼脲3号','悬浮剂','茶','1500倍液',NULL,'人工摘除虫茧及群集幼虫；保护利用瓢虫、小茧蜂等天敌；药剂防治可选用25%灭幼脲3号悬浮剂1500倍液、或5%高效氯氟氰菊酯微乳剂2000倍液，在幼虫3龄前喷雾，重点喷施叶背。','llm',0,'2026-11-02 07:00:14'),(71,'二硫化碳',NULL,'葡萄','灌注',NULL,'严格检疫，禁从疫区调运苗木；选用抗性砧木（如‘和谐’‘5A’）嫁接；土壤处理可用50%辛硫磷500克拌细土50公斤，亩施25公斤；亦可用二硫化碳灌注。','llm',0,'2026-11-02 07:00:17'),(72,'乙螨唑',NULL,'葡萄',NULL,NULL,'早春喷施波美3–5度石硫合剂；秋后清理病叶；生长季可选用螺螨酯、联苯肼酯、乙螨唑或阿维菌素等药剂防控，注意轮换用药以延缓抗性。','llm',0,'2026-11-02 07:00:22'),(73,'印楝素','悬浮剂','葡萄',NULL,NULL,'冬季刮除老树皮消灭越冬雌螨；发生期喷施1.8%阿维菌素乳油1000倍液，或0.5%印楝素悬浮剂、0.3%苦参碱水剂；可结合释放天敌尼氏钝绥螨进行生物防治。','llm',0,'2026-11-02 07:00:25'),(74,'甲氨基阿维菌素苯甲酸盐','水分散粒剂','辣椒','4000–6000倍液',NULL,'可选用22.4%螺虫乙酯悬浮剂2000–3000倍液、1.3%苦参碱水剂或5.7%甲氨基阿维菌素苯甲酸盐水分散粒剂4000–6000倍液喷雾防治，重点喷施植株上部嫩叶背面及生长点。','llm',0,'2026-11-02 07:00:32'),(75,'溴氰虫酰胺','悬浮剂','黄瓜','2000倍液喷雾',NULL,'农业防治：清除残株、黄板诱杀成虫；生物防治：释放丽蚜小蜂；化学防治：可选用25%噻虫嗪水分散粒剂3000倍液或10%溴氰虫酰胺悬浮剂2000倍液喷雾，重点喷施叶背，7–10天1次，连防2–3次。','llm',0,'2026-11-02 07:00:50'),(76,'阿维·印楝素','乳油','葡萄',NULL,NULL,'可选用1.3%苦参碱水剂、50%啶虫脒水分散粒剂或0.8%阿维·印楝素乳油喷雾防治，重点喷施叶背，结合黄板诱杀与清园除草等农业措施。','llm',0,'2026-11-02 07:00:54'),(77,'氰戊菊酯','乳油','柑橘','3000倍液',NULL,'人工摘除卵块及低龄幼虫；生物防治可释放赤眼蜂；药剂防治可在幼虫3龄前喷施2.5%溴氰菊酯乳油2000倍液或20%氰戊菊酯乳油3000倍液。','llm',0,'2026-11-02 07:00:56'),(78,'乙唑螨腈',NULL,'柑橘',NULL,NULL,'春秋季为重点防治期，可选用联苯肼酯、乙唑螨腈或新型植物源药剂滨蒿内酯（6,7-二甲氧基香豆素）喷雾防治；注意轮换用药，保护捕食螨等天敌。','llm',0,'2026-11-02 07:01:00'),(79,'滨蒿内酯',NULL,'柑橘',NULL,NULL,'春秋季为重点防治期，可选用联苯肼酯、乙唑螨腈或新型植物源药剂滨蒿内酯（6,7-二甲氧基香豆素）喷雾防治；注意轮换用药，保护捕食螨等天敌。','llm',0,'2026-11-02 07:01:00'),(80,'杀扑磷','乳油','柑橘','1000 倍液',NULL,'抓住初孵若虫期（5月下旬至6月中旬）喷药防治，可选用40%杀扑磷乳油1000倍液、25%扑虱灵可湿性粉剂1000倍液或10%吡虫啉可湿性粉剂1500倍液；结合冬季修剪虫枝、释放蜡蚧啮小蜂等天敌进行综合防控。','llm',0,'2026-11-02 07:01:09'),(81,'扑虱灵','可湿性粉剂','柑橘','1000 倍液',NULL,'抓住初孵若虫期（5月下旬至6月中旬）喷药防治，可选用40%杀扑磷乳油1000倍液、25%扑虱灵可湿性粉剂1000倍液或10%吡虫啉可湿性粉剂1500倍液；结合冬季修剪虫枝、释放蜡蚧啮小蜂等天敌进行综合防控。','llm',0,'2026-11-02 07:01:09'),(82,'虫螨腈',NULL,'柑橘',NULL,NULL,'农业防治：合理修剪、改善通风透光；物理防治：悬挂黄色诱虫板；生物防治：保护利用寄生蜂、瓢虫及韦伯虫座孢菌；化学防治：若虫盛发期喷施虫螨腈或联苯菊酯。','llm',0,'2026-11-02 07:01:19'),(83,'氯氰·毒死蜱','乳油','柑橘','1500 倍液',NULL,'采用雌雄同诱同杀策略，如甲基丁香酚+毒死蜱诱杀剂组合诱捕；结合农业清理（及时摘除虫果深埋或煮沸处理）、果实套袋、释放寄生蜂，并在成虫羽化盛期喷施20%氯氰·毒死蜱乳油1500倍液。','llm',0,'2026-11-02 07:01:25'),(84,'甲维氟铃脲','水分散粒剂','大豆','1000–1500倍液喷雾',NULL,'农业防治（清除杂草、翻耕灭蛹）、物理防治（黑光灯或性诱剂诱杀成虫）、生物防治（斜纹夜蛾核型多角体病毒、苏云金杆菌）；药剂防治宜在3龄前施药，推荐使用10.5%甲维氟铃脲水分散粒剂1000–1500倍液喷雾。','llm',0,'2026-11-02 07:01:30'),(85,'氟啶虫酰胺','水分散粒剂','柑橘','2500倍液',NULL,'农业防治：及时修剪虫枝、清除杂草；物理防治：悬挂黄色粘虫板；生物防治：保护利用瓢虫、草蛉、食蚜蝇等天敌；药剂防治：新梢蚜株率达25%时喷施25%噻虫嗪水分散粒剂3000倍液或10%氟啶虫酰胺水分散粒剂2500倍液。','llm',0,'2026-11-02 07:01:36'),(86,'乙基多杀菌素','悬浮剂','茶树','1500倍液',NULL,'优先采用蓝色粘虫板物理诱杀；释放捕食性天敌如小花蝽、胡瓜钝绥螨；药剂可选用乙基多杀菌素（20%悬浮剂1500倍液）或联苯菊酯（10%乳油2000倍液），注意轮换用药以延缓抗性。','llm',0,'2026-11-02 07:01:45');
